function squareFreeSubsets(nums) {
  // A valid choice uses each square-free value above 1 at most once (two copies of v put v*v in the product),
  // the chosen values must share no prime, and every 1 may be taken or not.
  const MOD = 1000000007;
  const copies = new Map();
  let ones = 0;
  for (const v of nums) {
    if (v === 1) ones++;
    else copies.set(v, (copies.get(v) || 0) + 1);
  }
  const items = [];
  for (const [v, c] of copies) {
    let rest = v, ok = true;
    const factors = [];
    for (let d = 2; d <= rest; d++) {
      let e = 0;
      while (rest % d === 0) { rest /= d; e++; }
      if (e > 1) ok = false;
      if (e === 1) factors.push(d);
    }
    if (ok) items.push({ factors, c });
  }
  const walk = (i, used) => {
    if (i === items.length) return 1;
    let ways = walk(i + 1, used);
    if (items[i].factors.every(f => !used.includes(f))) ways = (ways + items[i].c * walk(i + 1, [...used, ...items[i].factors])) % MOD;
    return ways;
  };
  let result = walk(0, []);
  for (let i = 0; i < ones; i++) result = result * 2 % MOD;
  return (result - 1 + MOD) % MOD;
}

