function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 12);
  const oneRate = rand() * 0.5;
  const nums = Array.from({ length: n }, () => {
    if (rand() < oneRate) return 1;
    return 1 + Math.floor(rand() * 30);
  });
  return [nums];
}
